  const encoder = new TextEncoder();
  if (encoder.encode(text).byteLength <= maxBytes) return text;
  let end = text.length;
  while (encoder.encode(text.slice(0, end)).byteLength > maxBytes) end--;
  return text.slice(0, end);
};

